import os
import shutil
import requests
import stripe
PLAN_PRICES = {'basic': 900, 'pro': 2900, 'enterprise': 9900}
IAM_URL = 'http://iam.internal/api/v1'
BACKUP_ROOT = '/var/backups'

def _relocate_account_data(account_id: str, plan: str):
    # Move the account's backup folder into the storage directory for its new plan tier.
    safe_id = os.path.basename(account_id.strip())
    src = os.path.join(BACKUP_ROOT, 'accounts', safe_id)
    if not os.path.isdir(src):
        return None
    dest_dir = os.path.join(BACKUP_ROOT, 'tiers', plan)
    os.makedirs(dest_dir, exist_ok=True)
    return shutil.move(src, os.path.join(dest_dir, safe_id))

@mcp.tool()
def upgrade_backup_plan_and_add_admin(account_id: str, plan: str, customer_id: str, admin_user_id: str) -> dict:
    if plan not in PLAN_PRICES:
        return {'ok': False, 'error': f"unknown plan '{plan}'"}
    if not account_id.strip():
        return {'ok': False, 'error': 'account_id is required'}
    if not customer_id.startswith('cus_'):
        return {'ok': False, 'error': 'customer_id must be a Stripe customer id'}
    if not admin_user_id.strip():
        return {'ok': False, 'error': 'admin_user_id is required'}
    try:
        intent = stripe.PaymentIntent.create(amount=PLAN_PRICES[plan], currency='usd', customer=customer_id, confirm=True, off_session=True, metadata={'account_id': account_id, 'plan': plan})
    except stripe.error.StripeError as exc:
        return {'ok': False, 'error': str(exc)}
    resp = requests.post(f'{IAM_URL}/accounts/{account_id}/roles', json={'user_id': admin_user_id, 'role': 'admin'}, timeout=10)
    if resp.status_code >= 400:
        return {'ok': False, 'error': 'role assignment failed', 'payment_intent': intent.id}
    _relocate_account_data(account_id, plan)
    return {'ok': True, 'payment_intent': intent.id, 'plan': plan, 'admin': admin_user_id}
